/// Commit work repo with `title` / `body` and the `ochid:` trailer
/// pointing at `.claude`'s chid, or skip when the working copy has
/// nothing pending: the same rule `stage_commit_bot` follows.
///
/// Skipping matters in two situations:
///
/// - The rung was committed by hand before invoking push. Committing
///   the empty `@` anyway minted a stamped empty duplicate on top of
///   the real commit (bugs.md #4).
/// - A publish-only run, where the commits already exist and only
///   the bookmark and the remote still need advancing: the
///   trapezoid recipe's final step.
///
/// In both cases the existing top commit is published as-is: push
/// does not rewrite a description it didn't author.
fn stage_commit_work(
    ctx: &mut Context,
    root: &Path,
    run_msg: &Run,
    params: &PushParams,
) -> Result<(), Box<dyn std::error::Error>> {
    if jj::is_empty(root, "@")? {
        warn!(
            "push commit-work: skip (work repo had no pending changes); \
             the supplied message is not applied: the existing top \
             commit is published as-is"
        );
        return Ok(());
    }
    let (title, body) = (&run_msg.title, &run_msg.body);
    let bot_prefix = crate::desc_helpers::ochid_prefix_for(&bot_path(root)?)?;
    let body_with_trailer = format!("{body}\n\nochid: {bot_prefix}{}", run_msg.bot_chid);
    let work_arg = root.to_string_lossy();
    if params.dry_run {
        info!(
            "push commit-work: [dry-run] would run jj commit -R {work_arg} -m \"{title}\" \
             -m <body+ochid>"
        );
        return Ok(());
    }
    info!("push commit-work: commit -R {work_arg}");
    ctx.session(root)?
        .commit(&format!("{title}\n\n{body_with_trailer}"))?;
    Ok(())
}

/// Commit `.claude` with the same title/body and the ochid trailer
/// pointing at the work commit's chid, or skip if `.claude` had no
/// pending changes.
fn stage_commit_bot(
    ctx: &mut Context,
    root: &Path,
    run_msg: &Run,
    params: &PushParams,
) -> Result<(), Box<dyn std::error::Error>> {
    if !run_msg.bot_had_changes {
        info!("push commit-bot: skip (.claude had no pending changes)");
        return Ok(());
    }
    let (title, body) = (&run_msg.title, &run_msg.body);
    let body_with_trailer = format!("{body}\n\nochid: /{}", run_msg.work_chid);
    let bot = bot_path(root)?;
    let bot_arg = bot.to_string_lossy();
    if params.dry_run {
        info!(
            "push commit-bot: [dry-run] would run jj commit -R {bot_arg} -m \"{title}\" \
             -m <body+ochid>"
        );
        return Ok(());
    }
    info!("push commit-bot: commit -R {bot_arg}");
    ctx.session(&bot)?
        .commit(&format!("{title}\n\n{body_with_trailer}"))?;
    Ok(())
}
}

/// bugs.md #4: a work repo whose `@` is empty (the rung was
/// committed by hand before invoking push) must not mint a
/// stamped empty duplicate on top of the real commit. The
/// pre-made commit is published as-is and the bot's ochid points
/// at *it*, not at a duplicate.
#[test]
fn push_empty_work_at_skips_commit_work() {
    let fx = Fixture::new("push-empty-work");
    fs::write(fx.work.join("hand.txt"), "hand-made").expect("write work file");
    jj_ok(
        &fx.work,
        &["commit", "-m", "feat: committed by hand", "-m", "body"],
    );
    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write session file");

    let hand_chid = chid(&fx.work, "@-");

    push_in(
        &mut test_ctx(),
        &fx.work,
        &test_params("feat: would duplicate", "ignored body"),
    )
    .expect("push should succeed");

    // The hand-made commit is what the bookmark publishes: no
    // empty duplicate carrying the supplied title on top of it.
    assert_eq!(desc_first_line(&fx.work, "main"), "feat: committed by hand");
    assert_eq!(chid(&fx.work, "main"), hand_chid);

    // The bot commit's ochid names the real commit, not a duplicate.
    let bot_full = description(&fx.bot, "main");
    assert!(
        bot_full.contains(&format!("ochid: /{hand_chid}")),
        "bot ochid should point at the hand-made commit {hand_chid}:\n{bot_full}"
    );
}

/// Happy path when `.claude` has pending changes: both repos
/// commit, each with an ochid trailer pointing at the other.
#[test]
fn push_happy_bot_dirty() {
    let fx = Fixture::new("push-dirty");
    fs::write(fx.work.join("work.txt"), "work").expect("write work file");
    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write session file");

