/// A workspace init makes passes `validate-desc` on both sides, its
/// agent directory named anything: the trailers carry the sides'
/// labels, `/.claude` for the agent side, never the directory's name.
#[test]
fn cli_init_trailers_pass_validate_desc() {
    let fx = CliFixture::new("init-trailers-valid");
    let local = format!("--repo=local={}", fx.base.display());

    let fresh = fx.path("fresh");
    run_ok(
        fx.cmd()
            .arg("init")
            .arg(&fresh)
            .arg(&local)
            .args(["--agent-dir", ".sess"]),
    );

    let adopted = fx.path("adopted");
    std::fs::create_dir_all(&adopted).expect("mkdir adopted");
    // Its own bare parent, since both workspaces' bares share names.
    std::fs::create_dir_all(fx.path("bares")).expect("mkdir bares");
    std::fs::write(adopted.join("notes.txt"), "a record\n").expect("write notes");
    run_ok(
        fx.cmd()
            .arg("init")
            .arg(&adopted)
            .arg("--adopt")
            .arg(format!("--repo=local={}", fx.path("bares").display()))
            .args(["--agent-dir", ".sess"]),
    );

    for work in [&fresh, &adopted] {
        for repo in [work.clone(), work.join(".sess")] {
            run_ok(
                fx.cmd()
                    .args(["validate-desc", "-r", "@-", "-R"])
                    .arg(&repo),
            );
        }
    }
}
====
### validate-desc

Read-only scan of commit descriptions against the other repo. The other repo is read from
`.vc-config.md` (`repos.agent`) by default, or overridden with `--other-repo`. Reports status per
commit: `ok` (valid ochid), `lost` (ochid: lost), `none` (ochid: none), `err` (issues found), or
`miss` (no ochid trailer).

```
# Validate all ancestors of @ (reads other repo from .vc-config.md)
vc-x1 validate-desc @..

# Validate with explicit other repo
vc-x1 validate-desc --other-repo .claude @..

# Validate specific range
vc-x1 validate-desc -r @.. -n 20
```

Use `--help` for the full status label legend.

### fix-desc

Fix commit descriptions against the other repo. Default is dry-run, so use `--no-dry-run` to write
changes. Reads other repo from `.vc-config.md` by default.

```
# Dry-run: show what would be fixed
vc-x1 fix-desc @..

# Actually fix
vc-x1 fix-desc @.. --no-dry-run

# Add missing ochid trailers by matching title
vc-x1 fix-desc @.. --add-missing

# Limit fixes
vc-x1 fix-desc @.. --no-dry-run -m 3

# Use a fallback for IDs not found in other repo
vc-x1 fix-desc @.. --fallback /.claude/lost
```

