            let err = CommitParams::try_from(&args(scope, &fx.work)).unwrap_err();
            assert!(err.starts_with(&format!("commit {letter}:")), "{err}");
            assert!(err.contains("`-s b`"), "{err}");
        }
        let err = CommitParams::try_from(&args("p", &fx.bot)).unwrap_err();
        assert!(err.contains("the agent side"), "{err}");
    }

