/// the partner, its id already in the work commit's trailer.
fn commit_pair(
    ctx: &mut Context,
    work: &Path,
    agent: &Path,
    agent_now: bool,
    params: &CommitParams,
) -> Result<(), Box<dyn std::error::Error>> {
    preflight(work, "work", true)?;
    preflight(agent, "agent", false)?;
