1	//! The `commit` subcommand: make a rung's commit pair, one commit
2	//! per repo of a dual workspace, each stamped with the other's
3	//! change id, before anything is pushed.
4	//!
5	//! The pair is what the per-rung flow reviews: the description and
6	//! the diff together, as a commit, by `jj show @-` in either repo.
7	//! Nothing here reaches a remote, so a fix after the review is a
8	//! fold into the pair and never a remote rewrite, and `vc-x1 push`
9	//! has nothing left to write: it publishes what was reviewed.
10	//!
11	//! - `-s b` is the normal case. Both change ids are known before
12	//!   either commit is made, since a jj commit keeps the working
13	//!   copy's change id, so each trailer is written once and never
14	//!   predicted or restamped.
15	//! - `-s w` and `-s a` are refused in a dual workspace: a half is
16	//!   an unpaired commit, which is what the pair exists to prevent.
17	//! - `-s p` commits a plain repo with the title and body and no
18	//!   trailer, the same description discipline on a repo with no
19	//!   partner.
20	//! - The work side's `@` must hold a change, since a rung changes
21	//!   the work repo. The agent side's `@` is the session's journal
22	//!   and is committed as it stands.
23	//! - A failure after the first commit restores both repos from the
24	//!   `jj op` snapshots taken just before it, as push does inside its
25	//!   mutation window.
26	
27	use std::path::{Path, PathBuf};
28	
29	use clap::Args;
30	use log::{debug, info, warn};
31	
32	use crate::context::Context;
33	use crate::desc_helpers::ochid_prefix_for;
34	use crate::jj;
35	use crate::jj::{current_op_id, op_restore};
36	use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
37	use crate::subcommand::SubcommandRunner;
38	
39	/// Commit the working copies as a rung's pair, or a plain repo's
40	/// commit, with the given title and body.
41	#[derive(Args, Debug)]
42	pub struct CommitArgs {
43	    /// Where: a path in the workspace for `-s b`, its root or either
44	    /// repo, or the repo itself for `-s p` [default: the current
45	    /// directory]
46	    #[arg(short = 'R', long, value_name = "PATH")]
47	    pub repo: Option<PathBuf>,
48	
49	    /// Which repos, required: `b|both` makes the pair, `p|por`
50	    /// commits a plain repo, and `w` or `a` is refused
51	    #[arg(
52	        short = 's',
53	        long,
54	        value_name = "SCOPE",
55	        value_parser = parse_repo_scope,
56	        required = true,
57	        help = format!("Which repos, required: {REPO_SCOPE_FORMS}, `w` and `a` refused")
58	    )]
59	    pub scope: RepoScope,
60	
61	    /// Commit title, the Conventional Commit line
62	    #[arg(long, value_name = "STR", required = true)]
63	    pub title: String,
64	
65	    /// Commit body, the problem and its solutions
66	    #[arg(long, value_name = "STR", required = true)]
67	    pub body: String,
68	}
69	
70	/// Inputs to the commit op, flat, owned, clap-free: the repos `-s`
71	/// and `-R` resolved to, and the description.
72	#[derive(Debug)]
73	pub struct CommitParams {
74	    /// The pair, work then agent, or the one plain repo.
75	    pub target: Target,
76	    pub title: String,
77	    pub body: String,
78	}
79	
80	/// What `-s` resolved to.
81	#[derive(Debug)]
82	pub enum Target {
83	    /// A dual workspace's two repos, work then agent.
84	    Pair { work: PathBuf, agent: PathBuf },
85	    /// A plain repo with no partner.
86	    Por(PathBuf),
87	}
88	
89	impl TryFrom<&CommitArgs> for CommitParams {
90	    type Error = String;
91	
92	    /// Resolve the scope into its repos, refusing a half of a dual
93	    /// workspace, and check the description is not blank.
94	    fn try_from(a: &CommitArgs) -> Result<Self, String> {
95	        if a.title.trim().is_empty() || a.body.trim().is_empty() {
96	            return Err("commit: --title and --body must both be non-empty".into());
97	        }
98	        let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
99	            .map_err(|e| e.to_string())?;
100	        let target = match &a.scope {
101	            RepoScope::Por => match repos.as_slice() {
102	                [repo] => Target::Por(repo.clone()),
103	                other => {
104	                    return Err(format!(
105	                        "commit -s p: expected one repo, got {}",
106	                        other.len()
107	                    ));
108	                }
109	            },
110	            RepoScope::Sides(sides) if sides.is_both() => match repos.as_slice() {
111	                [work, agent] => Target::Pair {
112	                    work: work.clone(),
113	                    agent: agent.clone(),
114	                },
115	                other => {
116	                    return Err(format!(
117	                        "commit -s b: expected two repos, got {}",
118	                        other.len()
119	                    ));
120	                }
121	            },
122	            RepoScope::Sides(sides) => {
123	                let letter = if sides.has_bot() { "a" } else { "w" };
124	                return Err(format!(
125	                    "commit -s {letter}: a half of a dual workspace is an unpaired commit, \
126	                     which the pair exists to prevent. Use `-s b` for the pair, or `-s p -R <repo>` \
127	                     for a plain repo"
128	                ));
129	            }
130	        };
131	        Ok(CommitParams {
132	            target,
133	            title: a.title.clone(),
134	            body: a.body.clone(),
135	        })
136	    }
137	}
138	
139	impl SubcommandRunner for CommitArgs {
140	    type Params = CommitParams;
141	
142	    /// Delegate to the `TryFrom<&CommitArgs>` impl above.
143	    fn to_params(&self) -> Result<Self::Params, String> {
144	        CommitParams::try_from(self)
145	    }
146	
147	    /// Run the `commit` op.
148	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
149	        commit(ctx, params)
150	    }
151	}
152	
153	/// Entry point: the pair, or the plain commit.
154	pub fn commit(ctx: &mut Context, params: &CommitParams) -> Result<(), Box<dyn std::error::Error>> {
155	    debug!("commit: enter {params:?}");
156	    match &params.target {
157	        Target::Pair { work, agent } => commit_pair(ctx, work, agent, params),
158	        Target::Por(repo) => commit_por(ctx, repo, params),
159	    }
160	}
161	
162	/// Refuse a repo that cannot take the commit: a conflicted one, or
163	/// for the work side an empty `@`, since a rung changes the work
164	/// repo and an empty commit would carry a trailer naming nothing
165	/// worth reviewing.
166	fn preflight(
167	    repo: &Path,
168	    label: &str,
169	    must_change: bool,
170	) -> Result<(), Box<dyn std::error::Error>> {
171	    if jj::matches(repo, "conflicts()")? {
172	        return Err(format!(
173	            "commit: the {label} repo '{}' has conflicts: resolve them first",
174	            repo.display()
175	        )
176	        .into());
177	    }
178	    if must_change && jj::is_empty(repo, "@")? {
179	        return Err(format!(
180	            "commit: nothing to commit, the {label} repo's @ is empty ('{}')",
181	            repo.display()
182	        )
183	        .into());
184	    }
185	    Ok(())
186	}
187	
188	/// Make the pair: both change ids read from the working copies
189	/// first, then the work commit with the agent's id in its trailer
190	/// and the agent commit with the work's id in its own.
191	fn commit_pair(
192	    ctx: &mut Context,
193	    work: &Path,
194	    agent: &Path,
195	    params: &CommitParams,
196	) -> Result<(), Box<dyn std::error::Error>> {
197	    preflight(work, "work", true)?;
198	    preflight(agent, "agent", false)?;
199	    let work_chid = jj::chid_of(work, "@")?;
200	    let agent_chid = jj::chid_of(agent, "@")?;
201	    let agent_prefix = ochid_prefix_for(agent)?;
202	    let work_desc = format!(
203	        "{}\n\n{}\n\nochid: {agent_prefix}{agent_chid}",
204	        params.title, params.body
205	    );
206	    let agent_desc = format!("{}\n\n{}\n\nochid: /{work_chid}", params.title, params.body);
207	
208	    let snapshots = (current_op_id(work)?, current_op_id(agent)?);
209	    info!("commit work: {} -> @- {work_chid}", work.display());
210	    ctx.session(work)?.commit(&work_desc)?;
211	    info!("commit agent: {} -> @- {agent_chid}", agent.display());
212	    if let Err(e) = ctx.session(agent)?.commit(&agent_desc) {
213	        warn!("commit: restoring both repos after: {e}");
214	        if let Err(r) = op_restore(agent, &snapshots.1) {
215	            warn!("commit: agent repo restore failed: {r}");
216	        }
217	        if let Err(r) = op_restore(work, &snapshots.0) {
218	            warn!("commit: work repo restore failed: {r}");
219	        }
220	        return Err(e);
221	    }
222	    info!(
223	        "commit: the pair is made, review it with `jj show @- -R {}` and `jj show @- -R {}`",
224	        work.display(),
225	        agent.display()
226	    );
227	    Ok(())
228	}
229	
230	/// Commit a plain repo with the description and no trailer.
231	fn commit_por(
232	    ctx: &mut Context,
233	    repo: &Path,
234	    params: &CommitParams,
235	) -> Result<(), Box<dyn std::error::Error>> {
236	    preflight(repo, "plain", true)?;
237	    let chid = jj::chid_of(repo, "@")?;
238	    info!("commit: {} -> @- {chid}", repo.display());
239	    ctx.session(repo)?
240	        .commit(&format!("{}\n\n{}", params.title, params.body))?;
241	    Ok(())
242	}
