279	    /// `-s`, `--title`, and `--body` are required, and a blank
280	    /// description is refused at params time.
281	    #[test]
282	    fn scope_title_and_body_are_required() {
283	        let err = parse(&["vc-x1", "commit", "--title", "t", "--body", "b"]).unwrap_err();
284	        assert!(err.contains("--scope"), "{err}");
285	        let err = parse(&["vc-x1", "commit", "-s", "b", "--body", "b"]).unwrap_err();
286	        assert!(err.contains("--title"), "{err}");
287	        let fx = Fixture::new("commit-blank");
288	        let mut a = args("b", &fx.work);
