fn parse_switches_and_repo() {
    let a = parse(&["test", "-s", "p", "-R", "../other", "--step", "--dry-run", "--yes"]).unwrap();
    assert_eq!(a.scope, RepoScope::Por);
    assert_eq!(a.repo, Some(PathBuf::from("../other")));
    assert!(a.step && a.dry_run && a.yes);
}

