    assert!(!is_empty(&fx.bot, "@"), "the journal is still in @");

    push_in(&mut test_ctx(), &fx.work, &both(), &test_params()).expect("push");

    assert_eq!(chid(&fx.work, "main"), work_at);
    assert_eq!(chid(&fx.bot, "main"), agent_at, "the journal became the named partner");
    assert_eq!(desc_first_line(&fx.bot, "main"), "feat: two steps");
    let agent_desc = description(&fx.bot, "main");
    assert!(
        agent_desc.trim_end().ends_with(&format!("ochid: /{work_at}")),
