/// Build a `Run` carrying the ids a completed push would have.
fn completion_run(work_chid: String, agent_chid: String) -> Run {
    Run {
        bookmark: "main".to_string(),
        work_chid,
        agent: Some((AgentPlan::Fold, agent_chid)),
    }
}

